INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, content) VALUES ('Biomedical','Engineering',1,1,'Clinical Discovery & Design Inputs','Class III Cardiac Implant — translate surgeon needs into a Design Input Document and run an initial ISO 14971 risk pass.',100,'{"format":"staged","scenario":"You''re a junior R&D engineer at CardioMed. Dr. Patel (cardiothoracic surgeon) just shared interview transcripts about her pacemaker frustrations. Sarah Jenkins needs you to extract unmet needs, draft Design Inputs, and seed the risk file before Friday.","diagram_label":"Surgeon Interview Transcript — Excerpts","stages":[{"id":"needs","type":"decision_tree","title":"Stage 1 — Identify Unmet Clinical Needs","instruction":"From the transcripts, classify each surgeon statement as a true Unmet Need or a feature wish.","questions":[{"id":"n1","label":"\"The lead disconnects 4% of the time during MRI scans.\"","options":[{"value":"a","label":"Unmet need — patient safety hazard","correct":true},{"value":"b","label":"Feature request — nice to have","correct":false}]},{"id":"n2","label":"\"It would be great if the casing came in pink.\"","options":[{"value":"a","label":"Unmet need","correct":false},{"value":"b","label":"Cosmetic preference — not a design input","correct":true}]},{"id":"n3","label":"\"Battery life under 6 years means re-operation risk.\"","options":[{"value":"a","label":"Unmet need — drives a quantitative input","correct":true},{"value":"b","label":"Marketing claim","correct":false}]}],"feedback_correct":"Clean triage. These three feed Section 2 of the DID.","feedback_incorrect":"Re-read ISO 13485 §7.3.3 — design inputs must be verifiable."},{"id":"did","type":"component_selector","title":"Stage 2 — Translate to a Design Input","instruction":"Convert the MRI lead-disconnect need into a verifiable Design Input statement.","options":[{"value":"a","label":"Lead shall withstand a 100 N axial pull force without disconnect (ISO 5841-3).","correct":true,"feedback":"Quantitative, traceable, testable. Locked in."},{"value":"b","label":"Lead should be strong.","correct":false,"feedback":"Not verifiable — auditors will reject."},{"value":"c","label":"Lead must never fail.","correct":false,"feedback":"Absolute claims aren''t acceptable design inputs."}]},{"id":"risk","type":"decision_tree","title":"Stage 3 — ISO 14971 Hazardous Situation","instruction":"Map each hazard to its correct severity class (S1–S5).","questions":[{"id":"r1","label":"Lead disconnects → ventricular asystole","options":[{"value":"a","label":"S5 — Catastrophic","correct":true},{"value":"b","label":"S2 — Minor","correct":false}]},{"id":"r2","label":"Battery EOL alert delayed by 2 days","options":[{"value":"a","label":"S5 — Catastrophic","correct":false},{"value":"b","label":"S3 — Serious","correct":true}]}],"feedback_correct":"Risk file initialized. Mitigation strategies queued for Level 2.","feedback_incorrect":"Re-check ISO 14971 Annex C severity scales."},{"id":"review","type":"performance_review","title":"Performance Review","reviewer":"Sarah Jenkins, Lead R&D","criteria":["Needs identification","Design input quality","Risk classification"]}]}'::jsonb);
INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, content) VALUES ('Biomedical','Engineering',2,2,'R&D & CAD Coordination','Redline a CAD drawing, build the BOM in the eQMS, and balance biocompatibility against tensile strength.',120,'{"format":"staged","scenario":"The Mechanical team dropped a Rev B drawing of the pacemaker can. Procurement needs a BOM by Wednesday so we can release purchase orders. Marcus T. flagged a tolerance call you should review first.","diagram_label":"Pacemaker Can — Rev B Technical Drawing","stages":[{"id":"cad","type":"component_selector","title":"Stage 1 — CAD Redline","instruction":"Three call-outs are on the drawing. Which one needs a redline?","options":[{"value":"a","label":"Ø 9.50 ±0.05 mm bore — within ISO 286 H7 tolerance","correct":false,"feedback":"This call-out is dimensionally clean."},{"value":"b","label":"Coating: ''Parylene'' (no grade specified)","correct":true,"feedback":"Correct — must specify Parylene-C per USP Class VI for implantable use."},{"value":"c","label":"Material: Ti-6Al-4V ELI per ASTM F136","correct":false,"feedback":"Standard ELI titanium spec — already correct."}]},{"id":"bom","type":"component_selector","title":"Stage 2 — BOM Supplier Selection","instruction":"Pick the right supplier quote for the titanium can blank.","options":[{"value":"a","label":"Supplier A — $42/unit, ASTM F136 cert, 18-week lead","correct":false,"feedback":"Lead time blows the production window."},{"value":"b","label":"Supplier B — $38/unit, ASTM F136 cert, 6-week lead, ISO 13485 audited","correct":true,"feedback":"Cert + lead time + audit status balance."},{"value":"c","label":"Supplier C — $29/unit, no implant-grade cert","correct":false,"feedback":"No cert = automatic disqualification for Class III."}]},{"id":"mat","type":"material_slider","title":"Stage 3 — Material Sandbox (ISO 10993 vs Strength)","instruction":"Blend Titanium Grade 5 with PEEK reinforcement. Find a Factor of Safety ≥ 2.0 while minimizing stress shielding.","formula":"FoS = \\sigma_{yield} / \\sigma_{applied}","materials":[{"name":"PEEK","modulus_gpa":3.6,"yield_mpa":100,"bone_modulus_gpa":18},{"name":"Titanium Grade 5","modulus_gpa":114,"yield_mpa":880,"bone_modulus_gpa":18}],"applied_load_n":100,"cross_section_mm2":1,"fos_threshold":2,"feedback":"Locked. Material spec released to Procurement."},{"id":"review","type":"performance_review","title":"Performance Review","reviewer":"Marcus T., Quality","criteria":["CAD inspection","Supplier selection","Material trade-off"]}]}'::jsonb);
INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, content) VALUES ('Biomedical','Engineering',3,3,'V&V — Verification Protocols','Design a fatigue protocol, calculate sample size for 95/95 confidence, and execute a digital stress test.',150,'{"format":"staged","scenario":"Verification gate is in 14 days. You own the bench fatigue protocol for the lead-can interface. Statistics need to hold up under FDA scrutiny.","diagram_label":"Fatigue Test Rig — Schematic","stages":[{"id":"proto","type":"component_selector","title":"Stage 1 — Test Protocol Design","instruction":"Pick the loading regime that mimics a 10-year cardiac cycle.","options":[{"value":"a","label":"Sine wave, 1.2 Hz, 400M cycles, 60–120 N","correct":true,"feedback":"Matches ISO 5841-2 accelerated cardiac fatigue."},{"value":"b","label":"Static load, 200 N, 24 hours","correct":false,"feedback":"Static loads don''t reveal fatigue failure modes."},{"value":"c","label":"Random impulse, 5 Hz, 1M cycles","correct":false,"feedback":"Doesn''t represent physiologic cardiac loading."}]},{"id":"sample","type":"decision_tree","title":"Stage 2 — Sample Size for 95/95","instruction":"Using n = k²σ²/δ² with k = 2.43, σ = 8 N, δ = 5 N — confirm the calculation.","questions":[{"id":"s1","label":"What is n (rounded up)?","options":[{"value":"a","label":"n = 16 specimens","correct":true},{"value":"b","label":"n = 6 specimens","correct":false},{"value":"c","label":"n = 30 specimens","correct":false}]},{"id":"s2","label":"Is 16 acceptable for an FDA submission?","options":[{"value":"a","label":"Yes — meets 95/95 reliability tolerance interval","correct":true},{"value":"b","label":"No — must always test 30","correct":false}]}],"feedback_correct":"Statistics defensible. Test plan released.","feedback_incorrect":"Recompute: 2.43² × 8² / 5² = 15.1 → round to 16."},{"id":"exec","type":"component_selector","title":"Stage 3 — Digital Stress Test Findings","instruction":"Sample 12/16 passed; 4 failed at 280M cycles. What''s the correct report entry?","options":[{"value":"a","label":"Conditional pass — investigate failure mode before VVR sign-off","correct":true,"feedback":"Right. Failure analysis required even with margin."},{"value":"b","label":"Outright pass — 75% > 50% threshold","correct":false,"feedback":"Reliability target was 95% — not met."},{"value":"c","label":"Hide the failures from the report","correct":false,"feedback":"Data falsification = career-ending and illegal."}]},{"id":"review","type":"performance_review","title":"Performance Review","reviewer":"Marcus T., Quality","criteria":["Protocol design","Statistical rigor","Reporting integrity"]}]}'::jsonb);
INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, content) VALUES ('Biomedical','Engineering',4,4,'Quality Systems & DHF Integrity','Audit the Design History File and run a CAPA investigation on a field failure.',150,'{"format":"staged","scenario":"Notified Body audit in 30 days. Sarah needs a DHF spot-check and a root cause investigation on a returned device from Berlin.","diagram_label":"Design History File — Index","stages":[{"id":"dhf","type":"decision_tree","title":"Stage 1 — DHF Spot Audit","instruction":"Flag the gaps in the DHF index.","questions":[{"id":"d1","label":"Design Review #3 minutes — no signature from Quality","options":[{"value":"a","label":"Gap — non-conformance","correct":true},{"value":"b","label":"Acceptable","correct":false}]},{"id":"d2","label":"Risk file references ISO 14971:2007 (superseded)","options":[{"value":"a","label":"Gap — must reference 2019 revision","correct":true},{"value":"b","label":"Acceptable — old standard fine","correct":false}]},{"id":"d3","label":"Design Output Rev 5 traced to Design Input Rev 5","options":[{"value":"a","label":"Gap","correct":false},{"value":"b","label":"Compliant traceability","correct":true}]}],"feedback_correct":"Two NCs logged, CAPA opened.","feedback_incorrect":"ISO 13485 §7.3.10 — DHF must be current and traceable."},{"id":"capa","type":"component_selector","title":"Stage 2 — Fishbone Root Cause","instruction":"Returned device shows premature battery drain. Which root cause does the fishbone point to?","options":[{"value":"a","label":"Method — telemetry duty cycle higher than spec''d","correct":true,"feedback":"Correct. Firmware patch + spec update required."},{"value":"b","label":"Material — battery chemistry defect","correct":false,"feedback":"Incoming inspection shows battery within spec."},{"value":"c","label":"Operator — surgeon implanted incorrectly","correct":false,"feedback":"Blaming the user before investigating is poor CAPA practice."}]},{"id":"review","type":"performance_review","title":"Performance Review","reviewer":"Sarah Jenkins, Lead R&D","criteria":["DHF audit accuracy","Root cause logic"]}]}'::jsonb);
INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, content) VALUES ('Biomedical','Engineering',5,5,'Clinical & Regulatory Strategy','Build a 510(k) substantial equivalence argument and design pivotal study criteria.',180,'{"format":"staged","scenario":"Reg Affairs lead Priya is preparing the FDA submission. You need to pick the right predicate and lock the inclusion criteria.","diagram_label":"FDA Predicate Device Database","stages":[{"id":"pred","type":"component_selector","title":"Stage 1 — Predicate Device Match","instruction":"Select the strongest substantial equivalence predicate.","options":[{"value":"a","label":"Medtronic Azure XT DR (K192847) — same indications, same energy delivery, modern predicate","correct":true,"feedback":"Best fit. Recent clearance with overlapping technology."},{"value":"b","label":"1998-cleared Telectronics device — outdated standards","correct":false,"feedback":"FDA prefers predicates within last 10 years."},{"value":"c","label":"An ICD (different indication)","correct":false,"feedback":"Wrong device class — not substantially equivalent."}]},{"id":"incl","type":"decision_tree","title":"Stage 2 — Pivotal Study Criteria","instruction":"Lock inclusion / exclusion rules for the pivotal trial.","questions":[{"id":"i1","label":"Adults 18–80 with symptomatic bradycardia → ","options":[{"value":"a","label":"Include","correct":true},{"value":"b","label":"Exclude","correct":false}]},{"id":"i2","label":"Patients with active endocarditis → ","options":[{"value":"a","label":"Include","correct":false},{"value":"b","label":"Exclude — implant contraindicated","correct":true}]},{"id":"i3","label":"Pregnant patients → ","options":[{"value":"a","label":"Include","correct":false},{"value":"b","label":"Exclude — no safety data","correct":true}]}],"feedback_correct":"Protocol locked. IRB submission ready.","feedback_incorrect":"Review ICH E6 GCP and 21 CFR 812 inclusion guidance."},{"id":"review","type":"performance_review","title":"Performance Review","reviewer":"Priya R., Reg Affairs","criteria":["Predicate logic","Trial design"]}]}'::jsonb);
INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, content) VALUES ('Biomedical','Engineering',6,6,'Manufacturing & Operations','Define IQ/OQ/PQ for a new molding line and balance supplier risk against cost.',180,'{"format":"staged","scenario":"Production transfer is next quarter. You''re qualifying the new injection molding cell for the header block and finalizing supplier contracts.","diagram_label":"Injection Molding Cell — Layout","stages":[{"id":"iqoqpq","type":"decision_tree","title":"Stage 1 — Process Validation","instruction":"Match each activity to the correct validation phase.","questions":[{"id":"v1","label":"Confirm machine arrived per purchase order, calibrated, installed correctly","options":[{"value":"a","label":"IQ — Installation Qualification","correct":true},{"value":"b","label":"PQ — Performance Qualification","correct":false}]},{"id":"v2","label":"Run 3 full production lots at nominal + worst case parameters","options":[{"value":"a","label":"OQ — Operational Qualification","correct":false},{"value":"b","label":"PQ — Performance Qualification","correct":true}]},{"id":"v3","label":"Test full operating range (temps, pressures) for output limits","options":[{"value":"a","label":"OQ — Operational Qualification","correct":true},{"value":"b","label":"IQ","correct":false}]}],"feedback_correct":"Validation master plan signed.","feedback_incorrect":"Reread GHTF SG3/N99-10:2004 process validation guide."},{"id":"src","type":"component_selector","title":"Stage 2 — Supplier Decision","instruction":"Three header block quotes. Choose the right balance.","options":[{"value":"a","label":"Vendor X — 12-week lead, $14/part, ISO 13485 + FDA-registered facility","correct":true,"feedback":"Reg-compliant + reasonable lead."},{"value":"b","label":"Vendor Y — 4-week lead, $9/part, ISO 9001 only (not 13485)","correct":false,"feedback":"Cheaper, but Class III demands ISO 13485."},{"value":"c","label":"Vendor Z — 26-week lead, $11/part, 13485 audited","correct":false,"feedback":"Lead time kills launch window."}]},{"id":"review","type":"performance_review","title":"Performance Review","reviewer":"Operations Director","criteria":["Validation rigor","Supplier judgment"]}]}'::jsonb);
INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, content) VALUES ('Biomedical','Engineering',7,7,'Leadership & Post-Market Surveillance','Defend the program at a Management Review and decide on a Field Safety Corrective Action.',200,'{"format":"staged","scenario":"You''re now program lead. Q3 board review is tomorrow, and post-market data from 12 months of European implants just landed.","diagram_label":"Post-Market Surveillance Dashboard","stages":[{"id":"gate","type":"component_selector","title":"Stage 1 — Management Review Stance","instruction":"Schedule slipped 6 weeks. Budget overrun is 8%. Pivotal data is strong. Pick your recommendation.","options":[{"value":"a","label":"Proceed to launch — accept overrun, frame schedule slip as risk-mitigating, present pivotal data as primary signal","correct":true,"feedback":"Defensible: efficacy data is the value driver. Transparency on cost."},{"value":"b","label":"Halt program — overruns are unacceptable","correct":false,"feedback":"Halting strong programs over 8% destroys value."},{"value":"c","label":"Hide the slip in a footnote","correct":false,"feedback":"Boards lose trust in leaders who bury bad news."}]},{"id":"fsca","type":"decision_tree","title":"Stage 2 — FSCA Trigger Decision","instruction":"Field data shows 0.18% rate of premature battery alert (predicted 0.05%). Is FSCA required?","questions":[{"id":"f1","label":"Does this exceed the risk file''s acceptable threshold?","options":[{"value":"a","label":"Yes — 3.6× predicted, exceeds tolerance","correct":true},{"value":"b","label":"No — still under 1%","correct":false}]},{"id":"f2","label":"Required action under MDR Article 87?","options":[{"value":"a","label":"Issue Field Safety Notice + report to Competent Authority within 15 days","correct":true},{"value":"b","label":"Wait for next annual review","correct":false}]}],"feedback_correct":"FSCA initiated. Patients notified, monitoring intensified.","feedback_incorrect":"EU MDR §87(1) — serious incidents require timely reporting."},{"id":"review","type":"performance_review","title":"Performance Review","reviewer":"Executive Steering Committee","criteria":["Strategic judgment","Patient safety priority"]}]}'::jsonb);